//! A protected install's limits must not change what an unprotected install renders. This renders
//! every built-in permission set for every cloud, with every binding target and the contexts the
//! management identity and the workloads use, and compares a digest of each result with
//! `golden/unprotected-render.json`, which was generated by the same test on the main branch
//! before protected installs had allow-lists.
//!
//! To refresh it after an intended change to a permission set or generator, run the test with
//! `UPDATE_UNPROTECTED_GOLDEN=1`, and review the diff of the golden file.

mod common;

use std::collections::BTreeMap;

use alien_permission_types::PermissionSet;
use alien_permissions::{
    generators::{
        AwsCloudFormationPermissionsGenerator, AwsRuntimePermissionsGenerator,
        AzureRuntimePermissionsGenerator, GcpRuntimePermissionsGenerator,
    },
    get_permission_set, list_permission_set_ids, BindingTarget, PermissionContext,
};
use common::create_test_context;
use serde::Serialize;
use sha2::{Digest, Sha256};

const GOLDEN: &str = "tests/golden/unprotected-render.json";

/// The one statement a built-in set carries that the main branch did not: a Deny on writes under
/// the signing settings path, rendered for every management role. It is a separate, tested part of
/// signed deployments, so the comparison leaves it out and the rest must match exactly. It is a
/// Deny on a path no unprotected setup writes, so it takes no permitted action from an install
/// that doesn't use signing.
const SIGNING_SETTINGS_GUARD: &str = "only-setup-changes-signing-settings";

fn without_signing_settings_guard(set: &PermissionSet) -> PermissionSet {
    let mut set = set.clone();
    if let Some(aws) = set.platforms.aws.as_mut() {
        aws.retain(|entry| entry.label.as_deref() != Some(SIGNING_SETTINGS_GUARD));
    }
    set
}

fn contexts() -> Vec<(&'static str, PermissionContext)> {
    vec![
        ("plain", create_test_context()),
        (
            "aws-boundary",
            create_test_context().with_aws_permissions_boundary_arn(
                "arn:aws:iam::123456789012:policy/my-stack-boundary",
            ),
        ),
        (
            "gcp-managing",
            create_test_context().with_managing_project_id("vendor-project"),
        ),
    ]
}

fn digest<T: Serialize>(rendered: alien_permissions::Result<T>) -> String {
    let text = match rendered {
        Ok(value) => serde_json::to_string(&value).expect("rendered output serializes"),
        Err(error) => format!("error {}: {}", error.code, error.message),
    };
    format!("{:x}", Sha256::digest(text.as_bytes()))
}

fn render_everything() -> BTreeMap<String, String> {
    let mut digests = BTreeMap::new();
    for id in list_permission_set_ids() {
        let set = &without_signing_settings_guard(get_permission_set(id).expect("listed set"));
        for (context_name, context) in contexts() {
            for (target_name, target) in [
                ("stack", BindingTarget::Stack),
                ("resource", BindingTarget::Resource),
            ] {
                let key = |cloud: &str| format!("{id} {cloud} {target_name} {context_name}");
                if set.platforms.aws.is_some() {
                    digests.insert(
                        key("aws"),
                        digest(
                            AwsRuntimePermissionsGenerator::new()
                                .generate_policy(set, target, &context),
                        ),
                    );
                    digests.insert(
                        key("aws-cloudformation"),
                        digest(
                            AwsCloudFormationPermissionsGenerator::new()
                                .generate_policy(set, target, &context),
                        ),
                    );
                }
                if set.platforms.azure.is_some() {
                    digests.insert(
                        key("azure"),
                        digest(
                            AzureRuntimePermissionsGenerator::new()
                                .generate_grant_plan(set, target, &context),
                        ),
                    );
                }
                if set.platforms.gcp.is_some() {
                    digests.insert(
                        key("gcp"),
                        digest(
                            GcpRuntimePermissionsGenerator::new()
                                .generate_grant_plan(set, target, &context),
                        ),
                    );
                }
            }
        }
    }
    digests
}

#[test]
fn an_unprotected_install_renders_every_built_in_set_as_before() {
    let rendered = render_everything();
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(GOLDEN);

    if std::env::var_os("UPDATE_UNPROTECTED_GOLDEN").is_some() {
        let mut text = serde_json::to_string_pretty(&rendered).expect("golden serializes");
        text.push('\n');
        std::fs::write(&path, text).expect("golden is writable");
        return;
    }

    let golden: BTreeMap<String, String> =
        serde_json::from_str(&std::fs::read_to_string(&path).expect("golden file exists"))
            .expect("golden file parses");
    assert!(golden.len() > 1000, "only {} golden entries", golden.len());

    let changed: Vec<&String> = golden
        .iter()
        .filter(|(key, digest)| rendered.get(*key) != Some(*digest))
        .map(|(key, _)| key)
        .collect();
    assert!(
        changed.is_empty(),
        "unprotected renders differ from the golden file: {changed:#?}"
    );
}
